def parse_duration(s: str) -> int:
    # '1h30m' -> 5400, '45s' -> 45, '2h' -> 7200
    units = {'h': 3600, 'm': 60, 's': 1}
    total, num = 0, ''
    for ch in s.strip():
        if ch.isdigit():
            num += ch
        elif ch in units and num:
            total += int(num) * units[ch]
            num = ''
        else:
            raise ValueError(f'bad duration: {s}')
    if num:
        raise ValueError(f'bad duration: {s}')
    return total

